var _userCache = null;
async function resolveUserCodes(inputs) {
  const client = getClient();
  if (!_userCache) {
    const result = await client.get(
      "Users",
      "$select=UserCode,UserName&$filter=Obsolete eq 0"
    );
    _userCache = result.value;
  }
  const codes = [];
  const displayParts = [];
  const unmatched = [];
  for (const input of inputs) {
    const trimmed = input.trim();
    const byCode = _userCache.find(
      (u) => u.UserCode.toUpperCase() === trimmed.toUpperCase()
    );
    if (byCode) {
      codes.push(byCode.UserCode);
      displayParts.push(`${byCode.UserName} (${byCode.UserCode})`);
      continue;
    }
    const term = trimmed.toUpperCase();
    const byName = _userCache.find((u) => {
      const name = (u.UserName || "").toUpperCase();
      return name === term || name.startsWith(term + " ") || name.endsWith(" " + term) || name.includes(term);
    });
    if (byName) {
      codes.push(byName.UserCode);
      displayParts.push(`${byName.UserName} (${byName.UserCode})`);
    } else {
      unmatched.push(trimmed);
    }
  }
  if (unmatched.length > 0) {
    const available = _userCache.map((u) => `${u.UserCode} \u2014 ${u.UserName}`).join("\n");
    throw new Error(
      `Could not match these users: ${unmatched.join(", ")}

Available users:
${available}`
    );
  }
  return { codes, display: displayParts.join(", ") };
}
async function fetchAll(entitySet, queryParams, pageSize = 500, maxPages = 50) {
  const client = getClient();
  const all = [];
  for (let page = 0; page < maxPages; page++) {
    const skip = page * pageSize;
    const params = `${queryParams}&$top=${pageSize}&$skip=${skip}`;
    const result = await client.get(entitySet, params);
    all.push(...result.value);
    if (result.value.length < pageSize) break;
  }
  return all;
}
