async function resolveCampaignActivity(campaignId, campaignActivityId) {
  const activities = await loadCampaignActivities(campaignId);
  if (activities.length === 0) {
    throw new Error(
      `Campaign ${campaignId} has no activities \u2014 cannot link an enquiry to it. Create at least one CampaignActivity first.`
    );
  }
  if (campaignActivityId !== void 0) {
    const chosen = activities.find((a) => a.CampaignActivityId === campaignActivityId);
    if (!chosen) {
      const list = activities.map((a) => `  ${a.CampaignActivityId} \u2014 ${a.Description ?? "(no description)"}`).join("\n");
      throw new Error(
        `CampaignActivityId ${campaignActivityId} does not belong to campaign ${campaignId}. Activities under campaign ${campaignId}:
${list}`
      );
    }
    return chosen;
  }
  return activities[0];
}
