async function addContactToCampaign(args) {
  const client = getClient();
  await client.getById("Contacts", args.contactId, "$select=ContactId");
  const activity = await resolveCampaignActivity(args.campaignId, args.campaignActivityId);
  const existing = await findExistingMembership(activity.CampaignActivityId, args.contactId);
  if (existing) {
    return [
      `No change \u2014 contact ${args.contactId} is already on the roster for activity ${activity.CampaignActivityId}${activity.Description ? ` ("${activity.Description}")` : ""}.`,
      existing.Comments ? `Existing comment: "${existing.Comments}".` : ""
    ].filter(Boolean).join("\n");
  }
  const body = {
    CampaignActivityId: activity.CampaignActivityId,
    ContactId: args.contactId
  };
  if (args.comments) body.Comments = args.comments;
  await client.post("CampaignActivityContacts", body);
  return `Added contact ${args.contactId} to campaign ${args.campaignId} via activity ${activity.CampaignActivityId}${activity.Description ? ` ("${activity.Description}")` : ""}.` + (args.campaignActivityId === void 0 ? `
(No campaignActivityId supplied \u2014 defaulted to the campaign's lowest-id activity.)` : "");
}
async function removeContactFromCampaign(args) {
  const client = getClient();
  const activity = await resolveCampaignActivity(args.campaignId, args.campaignActivityId);
  const existing = await findExistingMembership(activity.CampaignActivityId, args.contactId);
  if (!existing) {
    return `No change \u2014 contact ${args.contactId} is not on the roster for activity ${activity.CampaignActivityId}${activity.Description ? ` ("${activity.Description}")` : ""}.`;
  }
  const compositeKey = `CampaignActivityId=${activity.CampaignActivityId},ContactId=${args.contactId}`;
  await client.delete("CampaignActivityContacts", compositeKey);
  return `Removed contact ${args.contactId} from campaign ${args.campaignId} via activity ${activity.CampaignActivityId}${activity.Description ? ` ("${activity.Description}")` : ""}.`;
}
async function listCampaignContacts(args) {
  const client = getClient();
  const activity = await resolveCampaignActivity(args.campaignId, args.campaignActivityId);
  const params = [
    `$filter=CampaignActivityId eq ${activity.CampaignActivityId}`,
    `$expand=Contact($select=ContactId,Forename,Surname,Email,JobTitle;$expand=Division($select=DivisionId,Name))`,
    `$select=CampaignActivityId,ContactId,Comments,Created,CreatedByUserId`,
    `$orderby=Created desc`,
    `$top=${args.top ?? 200}`,
    `$count=true`
  ].join("&");
  const result = await client.get("CampaignActivityContacts", params);
  const total = result["@odata.count"];
  const rows = result.value;
  if (rows.length === 0) {
    return `No contacts on the roster for activity ${activity.CampaignActivityId}` + (activity.Description ? ` ("${activity.Description}")` : "") + ` under campaign ${args.campaignId}.`;
  }
  const lines = rows.map((r) => {
    const contact = r.Contact;
    const name = contact ? `${contact.Forename || ""} ${contact.Surname || ""}`.trim() || "(no name)" : "(contact deleted)";
    const division = contact?.Division?.Name || "\u2014";
    const job = contact?.JobTitle ? ` [${contact.JobTitle}]` : "";
    const comment = r.Comments ? ` \u2014 "${r.Comments.replace(/\s+/g, " ").slice(0, 80)}"` : "";
    const added = r.Created?.substring(0, 10) || "?";
    return `- **${name}**${job} @ ${division} (ContactId ${r.ContactId})${comment} \u2014 added ${added} by ${r.CreatedByUserId || "?"}`;
  });
  const header = `## Roster for activity ${activity.CampaignActivityId}` + (activity.Description ? ` ("${activity.Description}")` : "") + ` (campaign ${args.campaignId}) \u2014 ${rows.length}${total !== void 0 ? ` of ${total}` : ""}`;
  return [header, ...lines].join("\n");
}

