async function reportAccountFinancials(args) {
  const client = getClient();
  const div = await client.getById(
    "Divisions",
    args.divisionId,
    "$select=DivisionId,Name,SalesLedgerId"
  );
  const salesLedgerId = div.SalesLedgerId;
  const dateFilters = [];
  if (args.dateFrom) dateFilters.push(`InvoiceDate ge ${args.dateFrom}`);
  if (args.dateTo) dateFilters.push(`InvoiceDate le ${args.dateTo}`);
  const invFilters = [`OperatingCompanyCode eq 'A'`];
  if (salesLedgerId) invFilters.push(`SalesLedgerId eq '${salesLedgerId}'`);
  invFilters.push(...dateFilters);
  const invParams = [
    `$filter=${invFilters.join(" and ")}`,
    `$select=InvoiceNumber,CreditNoteNumber,InvoiceDate,NetValue,GrossValue,CustomerReference`,
    `$orderby=InvoiceDate desc`,
    `$top=${args.top || 50}`
  ].join("&");
  const invoices = await client.get("SalesInvoiceHeaders", invParams);
  const txFilters = [];
  if (salesLedgerId) txFilters.push(`Account eq '${salesLedgerId}'`);
  txFilters.push(...dateFilters);
  const txParams = [
    txFilters.length > 0 ? `$filter=${txFilters.join(" and ")}` : "",
    `$select=InvoiceNumber,OrderNumber,ProductItemId,ProductDescription,TransactionType,CalculatedInvoiceQuantity,CalculatedPrice,CalculatedLineValue,InvoiceDate`,
    `$orderby=InvoiceDate desc`,
    `$top=${args.top || 50}`
  ].filter(Boolean).join("&");
  const transactions = await client.get("SalesTransactions", txParams);
  let totalNet = 0;
  let totalGross = 0;
  for (const inv of invoices.value) {
    totalNet += inv.NetValue || 0;
    totalGross += inv.GrossValue || 0;
  }
  let output = [
    `# Financial Summary \u2014 ${div.Name}`,
    `**DivisionId:** ${args.divisionId}`,
    `**Account Code:** ${salesLedgerId || "N/A"}`,
    args.dateFrom || args.dateTo ? `**Period:** ${args.dateFrom || "..."} to ${args.dateTo || "..."}` : "",
    "",
    `## Invoice Summary`,
    `**Total Invoices:** ${invoices.value.length}`,
    `**Total Net:** \xA3${totalNet.toFixed(2)}`,
    `**Total Gross:** \xA3${totalGross.toFixed(2)}`
  ].filter(Boolean).join("\n");
  if (invoices.value.length > 0) {
    output += "\n\n### Recent Invoices\n";
    const invLines = invoices.value.slice(0, 20).map((inv) => {
      const date3 = inv.InvoiceDate?.substring(0, 10) || "N/A";
      return `- ${inv.InvoiceNumber}${inv.CreditNoteNumber ? ` (CN: ${inv.CreditNoteNumber})` : ""} | ${date3} | Net: \xA3${inv.NetValue?.toFixed(2) ?? "0.00"} | Ref: ${inv.CustomerReference || "N/A"}`;
    });
    output += invLines.join("\n");
  }
  if (transactions.value.length > 0) {
    output += `

## Recent Transactions (${transactions.value.length})
`;
    const txLines = transactions.value.slice(0, 30).map((t) => {
      const date3 = t.InvoiceDate?.substring(0, 10) || "N/A";
      return `- ${t.ProductItemId || "\u2014"}: ${t.ProductDescription || "N/A"} | ${t.TransactionType || "N/A"} | Qty: ${t.CalculatedInvoiceQuantity ?? 0} x \xA3${t.CalculatedPrice?.toFixed(2) ?? "0.00"} = \xA3${t.CalculatedLineValue?.toFixed(2) ?? "0.00"} | Inv: ${t.InvoiceNumber || "N/A"} | ${date3}`;
    });
    output += txLines.join("\n");
  }
  return output;
}

