function registerWriteTool(name, description, schema, handler) {
  const allowed = isWriteAllowed(name);
  const mapping = TOOL_PERMISSION_MAP[name] || { module: "unknown", action: "write" };
  const taggedDesc = allowed ? description : `[DISABLED \u2014 no ${mapping.module} ${mapping.action} permission] ${description}`;
  server.tool(name, taggedDesc, schema, async (args) => {
    if (!isWriteAllowed(name)) {
      const mapping2 = TOOL_PERMISSION_MAP[name] || { module: "unknown", action: "write" };
      const readOnly = resolveWriteAllow() === "";
      return {
        content: [{ type: "text", text: [
          `Permission denied: **${mapping2.action}** on **${mapping2.module}** module.`,
          ``,
          readOnly ? `This connector is in READ-ONLY mode. All writes are disabled.` : `This user does not have ${mapping2.action} permission for ${mapping2.module}.`,
          ``,
          `Contact your administrator to update permissions in the Admin Portal.`
        ].join("\n") }],
        isError: true
      };
    }
    return handler(args);
  });
}
