registerWriteTool(
  "send_quote_email",
  "Send a quote by email. SAFETY: this MCP can only email quotes back to the authenticated API user \u2014 never to customers, CCs, or BCCs. The to/cc/bcc parameters are accepted for compatibility but are ignored. To email a customer, use the ProspectCRM UI. Replicates the 7-call flow Prospect's own UI uses (MergeData \xD7 3, Documents POST for the PDF shell, DocumentAttachments/AttachExistingDocument to stage it, SendMessage). All inputs optional except quoteId \u2014 `subject`/`messageBody` render from the email template if omitted, `emailTemplateCode` defaults to '_EMLQC', `quoteTemplateCode` defaults to '_QUOTE'. If the user asks for a specific template (e.g. 'the Education template', 'the Versa Wall Pocket one'), call list_quote_templates first to find the matching DocumentTypeCode, then pass it via quoteTemplateCode (or emailTemplateCode for cover-email variants). Set attachPdf=false for body-only email. Returns the sent-email DocumentId + the attachment DocumentId \u2014 feed the latter to get_merge_output to retrieve the source document.",
  sendQuoteEmailSchema.shape,
  async (args) => {
    try {
      const result = await sendQuoteEmail(sendQuoteEmailSchema.parse(args));
      return { content: [{ type: "text", text: result }] };
    } catch (err) {
      return { content: [{ type: "text", text: `Error: ${err.message}` }], isError: true };
    }
  }
);
server.tool(
  "list_quote_templates",
  "List the DocumentTemplate codes usable for quote emails on this tenant \u2014 both cover-email templates (feed the code to send_quote_email's emailTemplateCode param) and PDF/document templates (feed to quoteTemplateCode). Call this first when the user wants a non-default template, so you can match their intent to an available code.",
  listQuoteTemplatesSchema.shape,
  async (args) => {
    try {
      const result = await listQuoteTemplates(args);
      return { content: [{ type: "text", text: result }] };
    } catch (err) {
      return { content: [{ type: "text", text: `Error: ${err.message}` }], isError: true };
    }
  }
);
server.tool(
  "get_merge_output",
  "Retrieve the rendered document blob produced by a send_quote_email call (or any other Default.SendMessage). Returns inferred filename, MIME type, and size. For large blobs (typical quote PDF is 50\u2013500 KB), pass `saveTo` to write the document to disk and get back only metadata \u2014 otherwise base64 bytes are embedded inline in the response.",
  getMergeOutputSchema.shape,
  async (args) => {
    try {
      const result = await getMergeOutput(getMergeOutputSchema.parse(args));
      return { content: [{ type: "text", text: result }] };
    } catch (err) {
      return { content: [{ type: "text", text: `Error: ${err.message}` }], isError: true };
    }
  }
);
async function main() {
  const transport = new StdioServerTransport();
  await server.connect(transport);
  console.error("ProspectCRM MCP server running on stdio");
}
main().catch((err) => {
  console.error("Fatal error starting MCP server:", err);
  process.exit(1);
});
